head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > dayMoveFixed]<br/>Calendar 컴포넌트에서 년/월을 탐색할때 변경되는 선택일의 일자를 유지할지 설정합니다.",
    "validation" : [
        "미설정(기본값 false) 시 컴포넌트에서 년/월을 탐색할때 이동된 년/월에 맞게 변경되는 선택일의 일자가 1일로 변경됩니다.",
        "true 설정 시 컴포넌트에서 년/월을 탐색할때 이동된 년/월에 맞게 변경되는 선택일의 일자를 유지합니다.",
        "true 설정 시 이동된 월에 선택일의 일자가 없는 경우 마지막 일자가 선택됩니다.",
        "false 설정 시 컴포넌트에서 년/월을 탐색할때 이동된 년/월에 맞게 변경되는 선택일의 일자가 1일로 변경됩니다.",
        "calendarValueType=year 이면 dayMoveFixed 속성은 동작하지 않습니다.",
        "calendarValueType=yearMonth 이면 dayMoveFixed 속성은 동작하지 않습니다.",        
        "변경된 선택일은 팝업 달력의 날짜 영역과 하단의 선택일에 반영됩니다.",
        "calendarValueType=yearMonthDate, yearMonthDateHour 일때 팝업 달력 하단에 선택일이 표시됩니다.",
        "년/월을 탐색할때 선택일이 변경되면 onchange 이벤트가 발생합니다.",
        "년/월을 탐색할때 선택일이 변경되면 onviewchange 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        dayMoveFixed : con_dayMoveFixed.getText(),
        calendarValueType : con_calendarValueType.getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick", "onchange", "onviewchange"]);

    $c.gcm.createLabel('label="dayMoveFixed 설정 후 달력에서 탐색 후 선택일 확인"', '', 'label1');
    await $c.gcm.createBasicCalendar(cList, eList);
}



scwin.btn_getSelectedDate_onclick = function (e) {
    // calendar 내부 currentDate 영역 (ID 패턴이 환경마다 다를 수 있어 target1.render 내부 검색)
    const element = target1.render.querySelector('[id$="_currentDate"]')
                 || target1.render.querySelector('[class*="currentDate"]');

    if (element) {
        wf_body_bottom.getObj("scwin").setReturnValue("선택일 : " + element.textContent);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue('currentDate 영역을 찾을 수 없음');
    }
};



// 년/월을 탐색할때 선택일이 변경되면 onchange 이벤트 발생
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 이벤트 발생] 선택일이 변경되어 onchange 핸들러 호출됨");
};



// 년/월을 탐색할때 선택일이 변경되면 onviewchange 이벤트 발생
scwin.target1_onviewchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onviewchange 이벤트 발생] 선택일이 변경되어 onviewchange 핸들러 호출됨");
};
